import type {IncomingMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = messageValidators[message.type];
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

const messageValidators: Record<string, (message: Record<string, unknown>) => ValidationResult> = Object.create(null);

messageValidators['user_message'] = validateUserMessage;
messageValidators.ping = validatePingMessage;
messageValidators['list_sessions'] = validateListSessionsMessage;

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const limit = message.limit;
  const before = message.before;

  if (hasInvalidLimit(limit)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  if (before !== undefined && !isSessionCursor(before)) {
    return {valid: false, error: 'list_sessions before must be a valid cursor'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      ...(limit !== undefined ? {limit} : {}),
      ...(before !== undefined ? {before} : {}),
    },
  };
}

function hasInvalidLimit(limit: unknown): boolean {
  if (limit === undefined) return false;
  return typeof limit !== 'number' || !isNonNegativeInteger(limit);
}

function isNonNegativeInteger(limit: number): boolean {
  return Number.isInteger(limit) && limit >= 0;
}

function isSessionCursor(value: unknown): value is {sessionId: string; updatedAt: string | number} {
  if (typeof value !== 'object' || value === null) {
    return false;
  }

  const cursor = value as Record<string, unknown>;

  return (
    typeof cursor.sessionId === 'string' &&
    cursor.sessionId.length >= 1 &&
    cursor.sessionId.length <= 128 &&
    isValidCursorDate(cursor.updatedAt)
  );
}

function isValidCursorDate(value: unknown): value is string | number {
  if (typeof value === 'string') return !Number.isNaN(Date.parse(value));
  return typeof value === 'number' && Number.isFinite(value) && !Number.isNaN(new Date(value).getTime());
}
import {validateMessage} from './validation.js';

describe('conversation list frame validation', () => {
  it('rejects an unknown type that collides with an object prototype member', () => {
    expect(validateMessage({type: 'toString'})).toEqual({
      valid: false,
      error: 'Unknown message type: toString',
    });
  });

  it('accepts a bare list_sessions frame and strips a client-supplied user id', () => {
    expect(validateMessage({type: 'list_sessions', userId: 'another-user'})).toEqual({
      valid: true,
      data: {type: 'list_sessions'},
    });
  });

  it('forwards a valid limit and cursor while stripping a client-supplied user id', () => {
    expect(
      validateMessage({
        type: 'list_sessions',
        limit: 20,
        before: {sessionId: 'session-1', updatedAt: '2026-10-31T10:00:00.000Z'},
        userId: 'another-user',
      })
    ).toEqual({
      valid: true,
      data: {
        type: 'list_sessions',
        limit: 20,
        before: {sessionId: 'session-1', updatedAt: '2026-10-31T10:00:00.000Z'},
      },
    });
  });

  it('rejects malformed list_sessions limits and cursors', () => {
    const invalidFrames = [
      {type: 'list_sessions', limit: '10'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-a-cursor'},
      {type: 'list_sessions', before: {sessionId: '', updatedAt: '2026-10-31T10:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 'a'.repeat(129), updatedAt: '2026-10-31T10:00:00.000Z'}},
      {type: 'list_sessions', before: {sessionId: 'session-1', updatedAt: 'not-a-date'}},
      {type: 'list_sessions', before: {sessionId: 'session-1', updatedAt: true}},
    ];

    for (const frame of invalidFrames) {
      expect(validateMessage(frame)).toEqual({valid: false, error: expect.any(String)});
    }
  });
});
